package com.wizzadrds.theworldremembers.behavior; import com.mojang.serialization.Codec; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.resources.Identifier; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class NpcBehaviorManager extends SavedData{private final Map<UUID,NpcBehaviorState> states=new HashMap<>(); private static final Codec<NpcBehaviorManager> CODEC=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),NpcBehaviorState.CODEC).xmap(m->{var x=new NpcBehaviorManager();x.states.putAll(m);return x;},x->x.states); private static final SavedDataType<NpcBehaviorManager> TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","behavior"),NpcBehaviorManager::new,CODEC,null); public static NpcBehaviorManager get(ServerLevel w){return w.getDataStorage().computeIfAbsent(TYPE);} public NpcBehaviorState getOrCreate(UUID id,long tick){return states.computeIfAbsent(id,k->NpcBehaviorState.idle(tick));} public void set(UUID id,NpcBehaviorState s){states.put(id,s);setDirty();} public NpcBehaviorState get(UUID id){return states.get(id);}}
